// Decomposition of a linear memory address (32-bit example)
uint32_t address = 0xFEEDC0DE;

// Define page structure (e.g., 4KB pages = 12 bits)
const int PAGE_BITS = 12;
const uint32_t PAGE_MASK = (1 << PAGE_BITS) - 1; // 0xFFF

// --- Extracting Components ---

// Offset (Low bits, isolated via AND)
uint32_t page_offset = address & PAGE_MASK;

// Page Number (High bits, isolated via Right Shift)
uint32_t page_number = address >> PAGE_BITS;

